-- GENERATED by report.py -- every sheet's base SQL (no dashboard filters applied)

-- ============ Business/Ease of Biz Correlation Sheet ============
SELECT * FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS LIMIT 0;
SELECT COUNTRY AS G, AVG(EASE_OF_BUSINESS) AS X, AVG(GDP/POPULATION_TOTAL) AS Y, AVG(EASE_OF_BUSINESS) AS C FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS  GROUP BY 1;

-- ============ Business/Ease of Biz Factors Sheet ============
SELECT DAYS_TO_START_BUSINESS AS C0, HOURS_TO_DO_TAX AS C1, BUSINESS_TAX_RATE AS C2, AVG(DAYS_TO_START_BUSINESS) AS M3, AVG(HOURS_TO_DO_TAX) AS M4, AVG(BUSINESS_TAX_RATE) AS M5 FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS  GROUP BY 1, 2, 3 LIMIT 200;

-- ============ Business/Ease of Biz Index ============
SELECT COUNTRY AS C0, AVG(BUSINESS_TAX_RATE) AS M1, AVG(DAYS_TO_START_BUSINESS) AS M2, AVG(EASE_OF_BUSINESS) AS M3, AVG(HOURS_TO_DO_TAX) AS M4 FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS WHERE COUNTRY IN ('American Samoa', 'Andorra', 'Aruba', 'Bermuda', 'Cayman Islands', 'Cuba', 'Curacao', 'Faeroe Islands', 'French Polynesia', 'Greenland', 'Guam', 'Isle of Man', 'Korea, Dem. Rep.', 'Liechtenstein', 'Macao SAR, China', 'Monaco', 'New Caledonia', 'Northern Mariana Islands', 'Sint Maarten (Dutch part)', 'Somalia', 'St. Martin (French part)', 'Turkmenistan', 'Turks and Caicos Islands', 'Virgin Islands (U.S.)') GROUP BY 1 LIMIT 200;

-- ============ Tourism/TourismOverTime ============
SELECT DATE_TRUNC('YEAR', DATE) AS T, SUM(TOURISM_INBOUND) AS VAL, REGION AS FLAG FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS WHERE DATE >= '2000-01-01' AND DATE <= '2012-01-01' GROUP BY 1, 3;

-- ============ Tourism/TourismByCountry ============
SELECT AVG(TOURISM_INBOUND) AS M0 FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS WHERE DATE >= '2000-01-01' AND DATE <= '2012-01-01';

-- ============ Population/Population ============
SELECT COUNTRY AS GEO_NAME, MAX(CASE WHEN (BIRTH_RATE)<0.015 THEN 'Below 1.5%' WHEN
(BIRTH_RATE)<0.03 THEN '1.5-3%' ELSE
'Above 3%' END) AS C FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS WHERE EXTRACT(YEAR FROM DATE) IN (2012) GROUP BY 1;

-- ============ Health/Health ============
SELECT COUNTRY AS DIM, AVG(HEALTH_EXP_GDP) AS VAL, CASE WHEN HEALTH_EXP_GDP>0.14 THEN 'Above Threshold' ELSE 'Below Threshold' END AS C FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS WHERE EXTRACT(YEAR FROM DATE) IN (2012) GROUP BY 1, 3 ORDER BY VAL DESC LIMIT 30;

-- ============ Technology/Technology ============
SELECT DATE_TRUNC('YEAR', DATE) AS T, AVG(MOBILE_PHONE_USAGE) AS VAL FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS  GROUP BY 1;

-- ============ Economy/Economy ============
SELECT DATE_TRUNC('YEAR', DATE) AS T, AVG(GDP) AS VAL, COUNTRY AS PANEL FROM SUPERSTORE.PUBLIC.WORLD_INDICATORS WHERE REGION IN ('The Americas') AND DATE >= '2000-01-01' AND DATE <= '2012-01-01' GROUP BY 1, 3;
